trigger_evidence:
Alert.alert(
      "Cancel Workorder",
      `Cancel ${trnId}? This action should only be used before field acceptance or after rejection.`,
      [
        { text: "NO", style: "cancel" },
        {
          text: "YES, CANCEL",
          style: "destructive",
          onPress: async () => {
            try {
              const result = await manageLifecycleInstruction({
                trnIds: [trnId],
                action: "CANCEL",
                cancelReason: "Cancelled from WDB Manager Control",
              }).unwrap();

              Alert.alert(
                "Work Cancelled",
                result?.message || "Lifecycle instruction cancelled.",
              );
            } catch (error) {
              console.log("WDB cancel ERROR", {
                trnId,
                code: error?.code,
                message: error?.message,
                data: error?.data,
                raw: error,
              });

              Alert.alert(
                "Cancel Failed",
                error?.data?.message ||
                  error?.message ||
                  "Could not cancel lifecycle instruction.",
              );
            }
          },
        },
      ],
    )

{
      ok: false,
      code: "INVALID_ASSIGNMENT_TARGETS",
      message:
        "assignment.targets must contain at least one USER, TEAM, or SP target",
    }

buildFailureResult(
        "UNAUTHORIZED_LCT_MANAGER",
        "Only MNG and SPV(MNC) can reassign or cancel lifecycle instructions",
        {
          actorRole: authority.role,
          actorSpId: authority.spId,
          actorIsMnc: authority.isMnc,
        },
      )

buildFailureResult(
        "TOO_MANY_TRNS",
        "A maximum of 50 TRNs can be managed at once",
        {
          count: trnIds.length,
        },
      )

buildFailureResult(
          "TRN_NOT_FOUND",
          "One or more TRNs were not found",
          {
            missingTrnIds,
          },
        )

buildFailureResult(
            "INVALID_MANAGED_LCT_TYPE",
            "Only INSPECTION, DISCONNECTION, RECONNECTION and REMOVAL instructions can be managed here",
            {
              trnId: row.trnId,
              trnType,
            },
          )

buildFailureResult(
            "INVALID_AST_ID",
            "TRN is missing ast.astData.astId",
            {
              trnId: row.trnId,
              trnType,
            },
          )

buildFailureResult(
            "AST_NOT_FOUND",
            "The referenced AST does not exist",
            {
              trnId: row.trnId,
              trnType,
              astId,
            },
          )

buildFailureResult(
            "TRN_ALREADY_COMPLETED",
            "Completed lifecycle instructions cannot be reassigned or cancelled",
            {
              trnId: row.trnId,
              trnType,
              workflowState,
            },
          )

buildFailureResult(
            "TRN_ALREADY_CANCELLED",
            "Cancelled lifecycle instructions cannot be changed",
            {
              trnId: row.trnId,
              trnType,
              workflowState,
            },
          )

buildFailureResult(
            "TRN_IN_PROGRESS",
            "In-progress lifecycle instructions cannot be reassigned or cancelled",
            {
              trnId: row.trnId,
              trnType,
              workflowState,
            },
          )

buildFailureResult(
            "INVALID_REASSIGN_STATE",
            "Only ISSUED or REJECTED lifecycle instructions can be reassigned",
            {
              trnId: row.trnId,
              trnType,
              workflowState: workflowState || "NAv",
            },
          )

buildFailureResult(
            "INVALID_CANCEL_STATE",
            "Only ISSUED or REJECTED lifecycle instructions can be cancelled",
            {
              trnId: row.trnId,
              trnType,
              workflowState: workflowState || "NAv",
            },
          )
